namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "New comment on your pull request",
        "Build succeeded for branch main",
        "Deployment to staging completed",
        "Security alert: dependency update available",
        "New team member joined the project",
        "Code review requested",
        "Issue #42 was closed",
        "Pipeline failed on branch feature/auth",
        "Release v2.1.0 published",
        "Disk usage exceeded 80% on prod-server-3"
    ];

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        lock (_lock)
        {
            var items = new List<NotificationItem>();
            for (var i = 0; i < 5; i++)
            {
                items.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = _templates[Random.Shared.Next(_templates.Length)],
                    Timestamp = DateTime.UtcNow.AddMinutes(-Random.Shared.Next(1, 60))
                });
            }
            return Task.FromResult(items);
        }
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync()
    {
        lock (_lock)
        {
            var items = new List<NotificationItem>();
            if (Random.Shared.Next(3) == 0) // ~33% chance of a new notification
            {
                items.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = _templates[Random.Shared.Next(_templates.Length)],
                    Timestamp = DateTime.UtcNow
                });
            }
            return Task.FromResult(items);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<NotificationItem>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state, or load fresh — never both.
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationSvc.GetInitialNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // Runs only in the interactive runtime — never during prerender.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newItems = await NotificationSvc.CheckForNewNotificationsAsync();
            if (newItems.Count > 0)
            {
                notifications.AddRange(newItems);
                PersistedNotifications = notifications;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

